-- doc_id: R06 · Agent 검증 질문의 기대값(정답지) 산출 SQL(읽기 전용) · 설명 = 30_현업요청대응/R06_Agent설정운영.md §2
-- 기대값은 GOLD 를 직접 집계해 만든다. Agent 답변과 이 값을 대조한다(반올림 · 단위는 R06 §2 표).
-- Q01 [MEMBER·EXECUTIVE] 2025년 회비 납부율(회비 납입 ÷ 회비 청구 · 기부금 제외)
SELECT ROUND(SUM(PAID_FEE_BILLABLE)/NULLIF(SUM(IFF(PAYMENT_TYPE='회비',BILLED_AMT,0)),0)*100,2) payment_rate_pct, SUM(IFF(PAYMENT_TYPE='회비',BILLED_AMT,0)) fee_billed, SUM(PAID_FEE_BILLABLE) fee_paid FROM GN_DW.GOLD.FACT_MEMBER_FEE WHERE MONTH_KEY BETWEEN 202501 AND 202512;
-- Q02 [EXECUTIVE] 연도별 편성예산·집행예산·집행율(FACT_BUDGET_YEARLY · 원)
SELECT BUDGET_YEAR, SUM(PLAN_BUDGET_YEAR) plan_amt, SUM(EXEC_BUDGET_YEAR) exec_amt, ROUND(SUM(EXEC_BUDGET_YEAR)/NULLIF(SUM(PLAN_BUDGET_YEAR),0)*100,2) exec_rate_pct FROM GN_DW.GOLD.FACT_BUDGET_YEARLY GROUP BY 1 ORDER BY 1;
-- Q03 [MEMBER] 2025년 신규 개발 회원수(고유 회원 · 사건 합계가 아님)
SELECT COUNT(DISTINCT MEMBER_DK) dev_members_distinct, SUM(DEV_MEMBERS) dev_members_sum_wrong FROM GN_DW.GOLD.FACT_MEMBER_EVENT WHERE DATE_SK BETWEEN 20250101 AND 20251231 AND DVLP_DIV_NM='신규';
-- Q04 [MEMBER] 2025년 서비스 발송 고유 회원수(발송 행 수가 아님)
SELECT COUNT(DISTINCT MEMBER_DK) send_members_distinct, COUNT(*) send_rows_wrong FROM GN_DW.GOLD.FACT_MESSAGE_DISPATCH WHERE DATE_SK BETWEEN 20250101 AND 20251231;
-- Q05 [MARKETING] 2025년 매체 광고비 합계(원)
SELECT SUM(AD_COST) ad_cost FROM GN_DW.GOLD.FACT_AD_PERFORMANCE WHERE PERF_DATE_SK BETWEEN 20250101 AND 20251231;
